                    pNextSeq = ServerSequence.EXIT_COMMON;
                    break;

                case InterruptCode.QUIT_ESCAPE:
                default:
                    pNextSeq = ServerSequence.EXIT_FADEOUT;
                    break;
            }
        }
		private bool isPokeCoverEscapeMode() {
            if (m_pMainModule.GetRule() == BtlRule.BTL_RULE_RAID)
                return false;

            if (m_pMainModule.GetCompetitor() != BtlCompetitor.BTL_COMPETITOR_WILD)
                return false;

            if (m_pMainModule.GetRule() != BtlRule.BTL_RULE_SINGLE)
                return false;

            return m_battleDriver.GetPokeChangeRequest().IsExist(BTL_CLIENT_ID.BTL_CLIENT_PLAYER);
