		private void seq_COVER_COMMAND_SWITCH(ref int pSeqStep, ref global::Dpr.Battle.Logic.ServerSequence pNextSeq) {
            switch (m_serverRequestGenerator.GetInterruptCode())
            {
                case InterruptCode.POKE_CHANGE:
                    pNextSeq = ServerSequence.INTERRUPT_POKECHANGE_POKESELECT;
                    break;

                case InterruptCode.POKE_COVER:
                    pNextSeq = ServerSequence.COVER_SELECT_START;
                    break;

                case InterruptCode.LEVELUP:
                    pNextSeq = ServerSequence.COVER_COMMAND;
                    break;

                case InterruptCode.QUIT_SHOWDOWN:
                    if (m_pMainModule.GetRule() == BtlRule.BTL_RULE_RAID)
                    {
                        pNextSeq = checkRaidBattleWin() ? ServerSequence.RAID_CAPTURE_START : ServerSequence.RAID_EXIT_LOSE;
                        break;
