                case InterruptCode.QUIT_ESCAPE:
                    pNextSeq = ServerSequence.EXIT_FADEOUT;
                    break;

                case InterruptCode.QUIT_TURNOVER:
                    m_pMainModule.NotifyBattleResult(BtlResult.BTL_RESULT_FORCE_QUIT, ResultCause.RESULT_CAUSE_TURNOVER);
                    pNextSeq = ServerSequence.EXIT_COMMON;
                    break;

                default:
                    pNextSeq = ServerSequence.ACTION_SELECT_START;
                    break;
            }
        }
		private bool irekae_IsNeedConfirm() {
            if (!m_pMainModule.IsIrekaeMode())
                return false;

            if (!m_battleDriver.GetPokeChangeRequest().IsExist())
                return false;

            if (m_battleDriver.GetPokeChangeRequest().IsExist(BTL_CLIENT_ID.BTL_CLIENT_PLAYER))
                return false;

            BTL_PARTY party = m_pBattleEnv.GetPokeCon().GetPartyData(m_pMainModule.GetPlayerClientID());
            return party.GetAliveMemberCount() > 1;
        }
		private byte irekae_GetEnemyPutPokeID() {
            Adapter adapter = m_clientData[(int)BTL_CLIENT_ID.BTL_CLIENT_ENEMY1].adapter;
            if (adapter != null)
            {
                unsafe
                {
                    ClientSendData.ACTION_SELECT* actionSelect = (ClientSendData.ACTION_SELECT*)adapter.GetReturnData().GetData();
                    BTL_ACTION_PARAM* action = (BTL_ACTION_PARAM*)actionSelect->actionParam;
                    if (BTL_ACTION.GetAction(*action) == BtlAction.BTL_ACTION_CHANGE)
                        return m_pBattleEnv.GetPokeCon().GetClientPokeDataConst((byte)BTL_CLIENT_ID.BTL_CLIENT_ENEMY1, action->change_memberIdx).GetID();
                }
            }
            return PokeID.INVALID;
        }
