		private void checkRaidBossCaptureResult() {
            // Advance the shared random sequence by 5 draws per client placed before this machine's client
            // (01fea0d8: myClientID * 5, byte counter).
            byte randSkipCount = (byte)(m_pMainModule.GetPlayerClientID() * 5);
            for (byte i = 0; i < randSkipCount; i++)
                calc.GetRand(0x10000);

            ServerSendData.RAIDBOSS_CAPTURE_RESULT result = default;
            checkRaidBossCaptureResult(ref result);
            m_serverRequestGenerator.SetSendData_RaidBossCaptureResult(result);

            byte myClientID = m_pMainModule.GetPlayerClientID();
            unsafe
            {
                if (result.isCaptured[myClientID])
                {
                    BTL_POKEPARAM boss = m_pBattleEnv.GetPokeCon().GetFrontPokeDataConst(BtlPokePos.POS_RAID_BOSS);
                    BallId ballID = Pml.Item.ItemData.GetBallID(result.itemno[myClientID]);
                    if (ballID == BallId.NULL)
                        ballID = BallId.MONSUTAABOORU;

                    boss.GetSrcData().SetMemories(Pml.PokePara.Memories.CAPTURED_BALL, (uint)ballID);
                    if (ballID == BallId.HURENDOBOORU)
                        boss.GetSrcData().SetFriendship(Capture.FRIENDBALL_FRIENDSHIP);
                }
            }
        }
		private void checkRaidBossCaptureResult(ref global::Dpr.Battle.Logic.ServerSendData.RAIDBOSS_CAPTURE_RESULT pResult) {
            for (int i = (int)BTL_CLIENT_ID.BTL_CLIENT_RAID_PLAYER_0; i <= (int)BTL_CLIENT_ID.BTL_CLIENT_RAID_PLAYER_3; i++)
            {
                if (isClientExist((BTL_CLIENT_ID)i))
                    checkRaidBossCaptureResult(ref pResult, (BTL_CLIENT_ID)i);
            }
        }
		private void checkRaidBossCaptureResult(ref global::Dpr.Battle.Logic.ServerSendData.RAIDBOSS_CAPTURE_RESULT pResult, global::Dpr.Battle.Logic.BTL_CLIENT_ID clientID) {
            bool isMustSuccess = false;
            int captureValueCoef = 0;

            ClientData clientData = m_clientData[(int)clientID];
            unsafe
            {
                if (!clientData.sendData_RaidBallSelect.isThrow)
                {
                    pResult.isThrow[(int)clientID] = false;
                    pResult.isCaptured[(int)clientID] = false;
                    return;
                }

                ushort itemID = clientData.sendData_RaidBallSelect.itemID;
                BTL_POKEPARAM pBoss = m_pBattleEnv.GetPokeCon().GetFrontPokeDataConst(BtlPokePos.POS_RAID_BOSS);
                BTL_POKEPARAM pUser = m_pBattleEnv.GetPokeCon().GetClientPokeDataConst((byte)clientID, 0);

                isMustSuccess = false;
                captureValueCoef = 4096;
                RaidBoss.GetCaptureValueCoef(ref captureValueCoef, ref isMustSuccess, m_pMainModule, pBoss);

                Capture.JudgeParam judgeParam = new Capture.JudgeParam();
                judgeParam.mainModule = m_pMainModule;
                judgeParam.battleEnv = m_pBattleEnv;
                judgeParam.targetPoke = pBoss;
                judgeParam.userPoke = pUser;
                judgeParam.itemID = itemID;
                judgeParam.captureValueCoef = captureValueCoef;
                judgeParam.isMustSuccess = isMustSuccess;
                judgeParam.isCriticalEnable = false;

                Capture.JudgeResult judgeResult = new Capture.JudgeResult();
                Capture.JudgeCapture(judgeResult, judgeParam);

                pResult.isThrow[(int)clientID] = true;
                pResult.itemno[(int)clientID] = itemID;
                pResult.isCaptured[(int)clientID] = judgeResult.isCaptured;
                pResult.yureCount[(int)clientID] = judgeResult.yureCount;
            }
        }
