            }
            pNextSeq = ServerSequence.EXIT_SWITCH;
        }
		private void seq_EXIT_SWITCH(ref int pSeqStep, ref global::Dpr.Battle.Logic.ServerSequence pNextSeq) {
            BtlResult result = m_pMainModule.GetBattleResult();
            switch (m_pMainModule.GetCompetitor())
            {
                case BtlCompetitor.BTL_COMPETITOR_WILD:
                    switch (result)
                    {
                        case BtlResult.BTL_RESULT_LOSE:
                        case BtlResult.BTL_RESULT_DRAW:
                            pNextSeq = ServerSequence.EXIT_WILD_LOSE;
                            break;

                        case BtlResult.BTL_RESULT_WIN:
                            pNextSeq = ServerSequence.EXIT_WILD_WIN;
                            break;

                        case BtlResult.BTL_RESULT_CAPTURE:
                            pNextSeq = ServerSequence.EXIT_WILD_CAPTURE;
                            break;

                        case BtlResult.BTL_RESULT_FORCE_QUIT:
                            if (m_pMainModule.GetBattleResultCause() == ResultCause.RESULT_SAFARI_BALL)
                                pNextSeq = ServerSequence.EXIT_FADEOUT;
                            else
                                pNextSeq = ServerSequence.EXIT_WILD_FORCE;
                            break;

                        default:
                            pNextSeq = ServerSequence.EXIT_FADEOUT;
                            break;
                    }
                    break;

                case BtlCompetitor.BTL_COMPETITOR_TRAINER:
                    pNextSeq = ServerSequence.EXIT_NPC;
                    break;

                case BtlCompetitor.BTL_COMPETITOR_INST:
                    pNextSeq = ServerSequence.EXIT_BATTLE_SPOT_TRAINER;
                    break;

                case BtlCompetitor.BTL_COMPETITOR_COMM:
                    pNextSeq = ServerSequence.EXIT_COMM;
                    break;

                default:
                    pNextSeq = ServerSequence.EXIT_FADEOUT;
                    break;
            }
        }
