                    pSeqStep++;
                    break;

                case 1:
                    if (waitAllAdapterReply())
                    {
                        resetAdapterCmd();
                        pSeqStep++;
                    }
                    break;

                case 2:
                    pNextSeq = ServerSequence.EXIT_FADEOUT;
                    break;
            }
        }
