                    {
                        resetAdapterCmd();
                        pNextSeq = ServerSequence.NEW_STARTUP_SWITCH;
                    }
                    break;
            }
        }
		private void seq_NEW_STARTUP_SWITCH(ref int pSeqStep, ref global::Dpr.Battle.Logic.ServerSequence pNextSeq) {
            // Resume from the oldest (smallest non-zero) serial number any client replied with.
            ushort serialNo = 0;
            for (int i = 0; i < (int)BTL_CLIENT_ID.BTL_CLIENT_NUM; i++)
            {
                Adapter adapter = m_clientData[i].adapter;
                if (adapter == null)
                    continue;

                SendData returnData = adapter.GetReturnData();
                ushort clientSerialNo = returnData.GetSerialNumber();
                if ((ushort)(clientSerialNo - 1) < (ushort)(serialNo - 1))
                {
                    pNextSeq = returnData.GetServerSequence();
                    serialNo = clientSerialNo;
                }
            }

            if (serialNo == 0)
            {
                pNextSeq = ServerSequence.BATTLE_START_SETUP;
                serialNo = 1;
            }

            m_sendDataSerialNo = serialNo;
        }
		private void notifyBattleResult() {
            BtlResult result = BattleResultJudge.CheckBattleResult(m_pMainModule, m_pBattleEnv.GetPokeCon(), m_pBattleEnv.GetDeadRec(), m_pBattleEnv.GetTimeLimit(), out ResultCause judgeCause);
            m_pMainModule.NotifyBattleResult(result, judgeCause);
        }
		private void checkBattleResult(out global::Dpr.Battle.Logic.BtlResult pResult, out global::Dpr.Battle.Logic.ResultCause pJudgeCause) {
            pResult = BattleResultJudge.CheckBattleResult(m_pMainModule, m_pBattleEnv.GetPokeCon(), m_pBattleEnv.GetDeadRec(), m_pBattleEnv.GetTimeLimit(), out pJudgeCause);
        }
		private bool checkRaidBattleWin() {
            if (m_pMainModule.GetRule() != BtlRule.BTL_RULE_RAID)
                return false;

            if (RaidBattle.IsLoseByPlayerDead(m_pMainModule))
            {
                if (m_pBattleEnv.GetPokeCon().GetPartyDataConst((uint)BTL_CLIENT_ID.BTL_CLIENT_PLAYER).GetAliveMemberCount() == 0)
                    return false;
            }

            if (m_pBattleEnv.GetRaidBattleStatus().IsAllDeadCountMax())
                return false;

            byte myClientID = m_pMainModule.GetPlayerClientID();
            for (byte clientID = 0; clientID < (byte)BTL_CLIENT_ID.BTL_CLIENT_NUM; clientID++)
            {
                if (!m_pMainModule.IsExistClient(clientID))
                    continue;
                if (!m_pMainModule.IsFriendClientID(myClientID, clientID))
                    continue;
                if (m_pBattleEnv.GetPokeCon().GetPartyDataConst(clientID).GetAliveMemberCount() == 0)
                    continue;

                // At least one friendly client can still fight: the raid is won when the boss is down.
                return m_pBattleEnv.GetPokeCon().GetFrontPokeDataConst(BtlPokePos.POS_RAID_BOSS).IsDead();
            }
            return false;
        }
		private global::Dpr.Battle.Logic.BtlRule getRule() {
            return m_pMainModule.GetRule();
        }
		private void storeClientInstruction() {
            for (int i = 0; i < (int)BTL_CLIENT_ID.BTL_CLIENT_NUM; i++)
            {
                m_clientInstruction.count[i] = 0;

                Adapter adapter = m_clientData[i].adapter;
                if (adapter != null)
                {
                    SendData returnData = adapter.GetReturnData();
                    unsafe
                    {
                        ClientSendData.ACTION_SELECT* actionSelect = (ClientSendData.ACTION_SELECT*)returnData.GetData();
                        returnData.GetDataSize();
                        for (int j = 0; j < actionSelect->actionNum; j++)
                        {
                            m_clientInstruction.param[i][j].raw = (long)actionSelect->actionParam[j];
                            m_clientInstruction.count[i]++;
                        }
                    }
                }
            }
        }
		private void clearClientInstruction() {
            for (int i = 0; i < (int)BTL_CLIENT_ID.BTL_CLIENT_NUM; i++)
                m_clientInstruction.count[i] = 0;
        }
		private void storeClientLimitTime() {
            for (byte i = 0; i < (byte)BTL_CLIENT_ID.BTL_CLIENT_NUM; i++)
            {
                Adapter adapter = m_clientData[i].adapter;
                if (adapter != null)
                {
                    unsafe
                    {
                        ClientSendData.CLIENT_LIMIT_TIME* limitTime = (ClientSendData.CLIENT_LIMIT_TIME*)adapter.GetReturnData().GetData();
                        m_pBattleEnv.GetTimeLimit().SetClientLimitTime(i, limitTime->limitTime);
                    }
                }
            }
        }
		private bool isClientLimitTimeOver() {
            if (!m_pMainModule.IsClientLimitTimeExist())
                return false;

            for (byte i = 0; i < (byte)BTL_CLIENT_ID.BTL_CLIENT_NUM; i++)
            {
                if (isClientExist((BTL_CLIENT_ID)i) && m_pBattleEnv.GetTimeLimit().GetClientLimitTime(i) == 0)
                    return true;
            }
            return false;
        }
		private void sendClientLimitTimeToLiveCupWatchMember() {
            uint num = 0;
            if (m_pMainModule.IsLiveCup() && m_pMainModule.CheckImServerMachine() && !m_pMainModule.IsWatchMember())
            {
                uint[] timeBuf = new uint[(int)BTL_CLIENT_ID.BTL_CLIENT_NUM];
                for (byte i = 0; i < (byte)BTL_CLIENT_ID.BTL_CLIENT_NUM; i++)
                    timeBuf[i] = m_pBattleEnv.GetTimeLimit().GetClientLimitTime(i);

                num = (uint)BTL_CLIENT_ID.BTL_CLIENT_NUM;
                m_pMainModule.SendClientTimerForLiveCupWatcher(timeBuf, num);
            }
        }
		private void sendRequest(global::Dpr.Battle.Logic.ServerRequest request) {
            unsafe
            {
                void* data = null;
                uint dataSize = 0;
                m_serverRequestGenerator.GenerateSendData(&data, ref dataSize, request, m_sendDataSerialNo);
                setSendDataInAllAdapter(m_sendDataSerialNo, m_currentSeq, request, data, dataSize);
                registerSendData(m_sendDataSerialNo, m_currentSeq, request, data, dataSize);
                m_sendDataSerialNo++;
            }
        }
		private void sendRequestAlone(global::Dpr.Battle.Logic.ServerRequest request, byte clientID) {
            sendRequestCore(request, clientID);
        }
		private void sendRequestCore(global::Dpr.Battle.Logic.ServerRequest request, byte clientID) {
            unsafe
            {
                void* data = null;
                uint dataSize = 0;
                m_serverRequestGenerator.GenerateSendData(&data, ref dataSize, request, m_sendDataSerialNo);

                if (clientID == (byte)BTL_CLIENT_ID.BTL_CLIENT_NULL)
                    setSendDataInAllAdapter(m_sendDataSerialNo, m_currentSeq, request, data, dataSize);
                else
                    setSendDataInSingleAdapter(m_sendDataSerialNo, m_currentSeq, request, data, dataSize, clientID);

                registerSendData(m_sendDataSerialNo, m_currentSeq, request, data, dataSize);
                m_sendDataSerialNo++;
            }
        }
		public unsafe void setSendDataInAllAdapter(ushort serialNumber, global::Dpr.Battle.Logic.ServerSequence serverSeq, global::Dpr.Battle.Logic.ServerRequest serverReq, void* sendData, uint dataSize) {
            for (int i = 0; i < (int)BTL_CLIENT_ID.BTL_CLIENT_NUM; i++)
            {
                Adapter adapter = m_clientData[i].adapter;
                if (adapter != null)
                    adapter.SetCmd(serialNumber, serverSeq, serverReq, sendData, dataSize);
            }
        }
		public unsafe void setSendDataInSingleAdapter(ushort serialNumber, global::Dpr.Battle.Logic.ServerSequence serverSeq, global::Dpr.Battle.Logic.ServerRequest serverReq, void* sendData, uint dataSize, byte clientID) {
            Adapter adapter = m_clientData[clientID].adapter;
            if (adapter != null)
            {
                adapter.ResetCmd();
                adapter.SetCmd(serialNumber, serverSeq, serverReq, sendData, dataSize);
            }
        }
		public unsafe void registerSendData(ushort serialNumber, global::Dpr.Battle.Logic.ServerSequence serverSeq, global::Dpr.Battle.Logic.ServerRequest serverReq, void* data, uint dataSize) {
            if (serialNumber != 0 && !m_pSendDataContainer.IsDataExist(serialNumber))
            {
                using (SendData sendData = new SendData(Allocator.Temp))
                {
                    sendData.Store(serialNumber, serverSeq, serverReq, data, dataSize);
                    m_pSendDataContainer.AddData(sendData);
                }
            }
        }
		private bool waitAllAdapterReply() {
            bool isAllReplied = true;
            for (int i = 0; i < (int)BTL_CLIENT_ID.BTL_CLIENT_NUM; i++)
            {
                Adapter adapter = m_clientData[i].adapter;
                if (adapter != null)
                    isAllReplied &= adapter.WaitCmd();
            }

            if (isAllReplied)
            {
                Net.Client.IncrementSeq();
                return true;
            }
            return false;
        }
		private void resetAdapterCmd() {
            for (int i = 0; i < (int)BTL_CLIENT_ID.BTL_CLIENT_NUM; i++)
            {
                Adapter adapter = m_clientData[i].adapter;
                if (adapter != null)
                    adapter.ResetCmd();
            }
        }
		private void initAllAdapter() {
            for (int i = 0; i < (int)BTL_CLIENT_ID.BTL_CLIENT_NUM; i++)
            {
                Adapter adapter = m_clientData[i].adapter;
                if (adapter != null)
                    adapter.Init();
            }
        }
		private void clearClientData() {
            for (int i = 0; i < (int)BTL_CLIENT_ID.BTL_CLIENT_NUM; i++)
                m_clientData[i].adapter = null;
        }
		private void setupClientData(global::Dpr.Battle.Logic.BTL_CLIENT_ID clientID, global::Dpr.Battle.Logic.Adapter adapter, global::Dpr.Battle.Logic.BTL_PARTY party) {
            m_clientData[(int)clientID].adapter = adapter;
            m_clientData[(int)clientID].party = party;
        }
		private global::Dpr.Battle.Logic.Adapter getClientAdapter(global::Dpr.Battle.Logic.BTL_CLIENT_ID clientID) {
            return m_clientData[(int)clientID].adapter;
        }
		private bool isClientExist(global::Dpr.Battle.Logic.BTL_CLIENT_ID clientID) {
            return m_clientData[(int)clientID].adapter != null;
        }
